-- Product schema remains compatible with the Python SQLAlchemy product model.
-- Runtime execution state belongs to the independent forge-store database.
CREATE TABLE users (id VARCHAR(32) PRIMARY KEY NOT NULL, username VARCHAR(80) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL);
CREATE TABLE sessions (token_hash VARCHAR(64) PRIMARY KEY NOT NULL, user_id VARCHAR(32) NOT NULL, expires_at VARCHAR(40) NOT NULL);
CREATE TABLE providers (id VARCHAR(32) PRIMARY KEY NOT NULL, name VARCHAR(100) NOT NULL, revision_id VARCHAR(32) NOT NULL, enabled BOOLEAN NOT NULL);
CREATE TABLE provider_revisions (id VARCHAR(32) PRIMARY KEY NOT NULL, provider_id VARCHAR(32) NOT NULL, config JSON NOT NULL, encrypted_key TEXT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE model_profiles (id VARCHAR(32) PRIMARY KEY NOT NULL, config JSON NOT NULL, version INTEGER NOT NULL);
CREATE TABLE agents (id VARCHAR(32) PRIMARY KEY NOT NULL, config JSON NOT NULL, version INTEGER NOT NULL);
CREATE TABLE projects (id VARCHAR(32) PRIMARY KEY NOT NULL, owner_id VARCHAR(32) NOT NULL, config JSON NOT NULL, base_commit VARCHAR(64) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE runs (id VARCHAR(32) PRIMARY KEY NOT NULL, project_id VARCHAR(32) NOT NULL, owner_id VARCHAR(32) NOT NULL, title VARCHAR(180) NOT NULL, request TEXT NOT NULL, status VARCHAR(40) NOT NULL, snapshot JSON NOT NULL, plan JSON, plan_digest VARCHAR(64) NOT NULL, artifact_digest VARCHAR(64) NOT NULL, report JSON NOT NULL, calls INTEGER NOT NULL, input_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, error TEXT NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE tasks (id VARCHAR(100) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, key VARCHAR(64) NOT NULL, kind VARCHAR(20) NOT NULL, agent_id VARCHAR(32) NOT NULL, title VARCHAR(180) NOT NULL, spec JSON NOT NULL, status VARCHAR(40) NOT NULL, messages JSON NOT NULL, result JSON NOT NULL, base_commit VARCHAR(64) NOT NULL, started_at VARCHAR(40) NOT NULL);
CREATE TABLE steps (id VARCHAR(160) PRIMARY KEY NOT NULL, state VARCHAR(20) NOT NULL, result JSON NOT NULL);
CREATE TABLE events (id INTEGER PRIMARY KEY NOT NULL, run_id VARCHAR(32), kind VARCHAR(60) NOT NULL, data JSON NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE agent_messages (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, sender_id VARCHAR(32) NOT NULL, recipient_id VARCHAR(32) NOT NULL, body TEXT NOT NULL, created_at VARCHAR(40) NOT NULL, delivered_at VARCHAR(40) NOT NULL);
CREATE TABLE local_activity_journal (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, name VARCHAR(60) NOT NULL, state VARCHAR(20) NOT NULL, result JSON NOT NULL, elapsed_s VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE outbox (id VARCHAR(32) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, action VARCHAR(40) NOT NULL, payload JSON NOT NULL, sent BOOLEAN NOT NULL, error TEXT NOT NULL, attempts INTEGER NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE orchestration_templates (id VARCHAR(32) PRIMARY KEY NOT NULL, config JSON NOT NULL, version INTEGER NOT NULL);
CREATE TABLE skills (id VARCHAR(32) PRIMARY KEY NOT NULL, name VARCHAR(64) UNIQUE NOT NULL, enabled BOOLEAN NOT NULL, latest_version INTEGER NOT NULL);
CREATE TABLE skill_revisions (id VARCHAR(80) PRIMARY KEY NOT NULL, skill_id VARCHAR(32) NOT NULL, version INTEGER NOT NULL, digest VARCHAR(64) NOT NULL, manifest JSON NOT NULL, files JSON NOT NULL, status VARCHAR(20) NOT NULL, approved_by VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE decision_requests (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, agent_id VARCHAR(32) NOT NULL, digest VARCHAR(64) NOT NULL, question JSON NOT NULL, status VARCHAR(20) NOT NULL, answer JSON NOT NULL, answered_by VARCHAR(32) NOT NULL, created_at VARCHAR(40) NOT NULL, answered_at VARCHAR(40) NOT NULL);
CREATE TABLE human_instructions (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, author_id VARCHAR(32) NOT NULL, recipients JSON NOT NULL, body TEXT NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE instruction_receipts (id VARCHAR(180) PRIMARY KEY NOT NULL, instruction_id VARCHAR(64) NOT NULL, task_id VARCHAR(100) NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE meetings (id VARCHAR(64) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, host_id VARCHAR(32) NOT NULL, participants JSON NOT NULL, subject VARCHAR(180) NOT NULL, agenda TEXT NOT NULL, status VARCHAR(32) NOT NULL, outcome JSON NOT NULL, created_at VARCHAR(40) NOT NULL, ended_at VARCHAR(40) NOT NULL);
CREATE TABLE action_items (id VARCHAR(100) PRIMARY KEY NOT NULL, run_id VARCHAR(32) NOT NULL, meeting_id VARCHAR(64) NOT NULL, owner_id VARCHAR(32) NOT NULL, task_key VARCHAR(64) NOT NULL, specification JSON NOT NULL, status VARCHAR(32) NOT NULL, origin JSON NOT NULL, created_at VARCHAR(40) NOT NULL);
CREATE TABLE platform_config (id VARCHAR(40) PRIMARY KEY NOT NULL, value JSON NOT NULL);
CREATE INDEX ix_action_items_run_id ON action_items(run_id);
CREATE INDEX ix_agent_messages_run_id ON agent_messages(run_id);
CREATE INDEX ix_agent_messages_recipient_id ON agent_messages(recipient_id);
CREATE INDEX ix_decision_requests_run_id ON decision_requests(run_id);
CREATE INDEX ix_events_run_id ON events(run_id);
CREATE INDEX ix_human_instructions_run_id ON human_instructions(run_id);
CREATE INDEX ix_instruction_receipts_instruction_id ON instruction_receipts(instruction_id);
CREATE INDEX ix_local_activity_journal_run_id ON local_activity_journal(run_id);
CREATE INDEX ix_meetings_run_id ON meetings(run_id);
CREATE INDEX ix_outbox_run_id ON outbox(run_id);
CREATE INDEX ix_outbox_sent ON outbox(sent);
CREATE INDEX ix_provider_revisions_provider_id ON provider_revisions(provider_id);
CREATE INDEX ix_runs_project_id ON runs(project_id);
CREATE INDEX ix_runs_status ON runs(status);
CREATE INDEX ix_sessions_user_id ON sessions(user_id);
CREATE INDEX ix_skill_revisions_skill_id ON skill_revisions(skill_id);
CREATE INDEX ix_tasks_run_id ON tasks(run_id);
